export function parseAmountToCents(value) {
  const match = String(value).trim().match(/^(-?)(\d+)(?:\.(\d{1,2}))?$/u);
  if (match === null) throw new TypeError("amount must have at most two decimal places");
  const [, sign, whole = "0", fraction = ""] = match;
  const cents = Number(whole) * 100 + Number(fraction.padEnd(2, "0"));
  if (!Number.isSafeInteger(cents)) throw new RangeError("amount is outside the safe range");
  return sign === "-" ? -cents : cents;
}
